const trezireOrganeCritice = async (lista) => { for (const organ of lista) { try { await global.registerOrgan(organ); await global.startHeartbeat(organ); console.log(`Organ ${organ} trezit.`); } catch (e) { console.error(`Eroare trezire ${organ}:`, e); } } }; const organeDeTrezit = ['hydraCreierCoordonator', 'hydraBursaQuant', 'hydraSistemImunitar', 'hydraSeifChei']; trezireOrganeCritice(organeDeTrezit);